import { CardSuit, CardValue } from "../../../common";
import { getCardData, IKlondikeCardData } from "./dataHelpers";
import { KlondikeStack, KlondikeStackType } from "./KlondikeStack";

type GameCardView = Phaser.GameObjects.GameObject;

export class KlondikeSolitaireRules {
  public readonly BASE_AMOUNT = 4;
  public readonly PILES_AMOUNT = 7;

  private readonly valueOrder: CardValue[] = ["ace", 2, 3, 4, 5, 6, 7, 8, 9, 10, "jack", "queen", "king"];

  constructor() {}

  /** карту можно двигать **/
  public isCardMovable(cardView: GameCardView, cardPile?: GameCardView[]): boolean {
    if (cardPile == null) return false;

    const cardData = getCardData(cardView);
    if (cardData == null) return false;

    const isTopCard = cardPile[cardPile.length - 1] === cardView;
    if (isTopCard) return true;

    if (cardData.stack.type !== KlondikeStackType.PILE) return false;

    // Минимальное правило: карта должна быть открыта.
    return cardData.side === "face";
  }

  /** получить карты, которые допустимо перетаскивать стопкой при клике на карте (только для PILE) */
  public getPileMovableCards (touchedCardView: GameCardView, cardPile: GameCardView[]): GameCardView[] {
    if (!cardPile || cardPile.length === 0) return [];

    // 1) Карта должна принадлежать этой стопке
    const startIndex = cardPile.indexOf(touchedCardView);
    if (startIndex === -1) return [];

    // 2) Достаём данные карты; карта должна быть настоящей "картой" и лежать именно в рабочей стопке (PILE)
    const touchedData = getCardData(touchedCardView);
    if (!touchedData || touchedData.stack.type !== KlondikeStackType.PILE) return [];

    // 3) По правилам Косынки перетаскивать можно только открытую карту (и открытую цепочку над ней)
    if (touchedData.side !== "face") return [];

    // 4) Если это верхняя карта стопки и она открыта — можно двигать её одну
    const isTop = startIndex === cardPile.length - 1;
    if (isTop) return [touchedCardView];

    // 5) Проверяем всю последовательность от touched до вершины стопки:
    //    - все карты должны быть открыты
    //    - каждая верхняя карта должна «цепляться» к нижней по правилу PILE
    //    cardPile упорядочен снизу-вверх, значит пары (нижняя, верхняя) идут как (i, i+1)
    for (let i = startIndex; i < cardPile.length - 1; i++) {
      const lowerView = cardPile[i];
      const upperView = cardPile[i + 1];

      const lower = getCardData(lowerView)?.card;
      const upper = getCardData(upperView)?.card;
      const lowerSide = getCardData(lowerView)?.side;
      const upperSide = getCardData(upperView)?.side;

      // 5.1) Любая закрытая карта внутри цепочки делает перенос недопустимым
      if (lowerSide !== "face" || upperSide !== "face") return [];

      // 5.2) Проверяем «чередование цвета» и «строго на 1 меньше» для верхней относительно нижней
      //      Внутри стопки: order(upper) = order(lower) - 1 и цвет противоположный
      //      Наша isPileChainable ожидает (top=верхняя, bottom=нижняя)
      if (!lower || !upper || !this.isPileChainable(upper, lower)) return [];
    }

    // 6) Если все пары валидны и все карты открыты — можно переносить всю верхнюю часть стопки
    return cardPile.slice(startIndex);
  }


  /** можно положить в базу сборки **/
  public canMoveToBase(movingCard: GameCardView, foundation: GameCardView[]): boolean {
    const moving = getCardData(movingCard)?.card;
    if (!moving) return false;

    const baseTop = foundation[foundation.length - 1];
    if (!baseTop) return moving.value === "ace";

    const top = getCardData(baseTop)?.card;
    if (!top) return moving.value === "ace";

    return this.isBaseChainable(moving, top);
  }

  public canDrop(movingCard: GameCardView, stack?: KlondikeStack): boolean {
    if (!stack) return false;

    switch (stack.data.type) {
      case KlondikeStackType.PILE:
        return this.canMoveToPile(movingCard, stack.getCards());
      case KlondikeStackType.BASE:
        return this.canMoveToBase(movingCard, stack.getCards());
      case KlondikeStackType.GRAVE:
      case KlondikeStackType.DECK:
      default:
        return false;
    }
  }

  /** можно положить в рабочую стопку для тасовки **/
  public canMoveToPile(movingCard: GameCardView, pile: GameCardView[]): boolean {
    const movingCardData = getCardData(movingCard)?.card;
    if (movingCardData == null) return false;

    const pileTop = pile[pile.length - 1];
    // ничего нет - можем класть только короля
    if (pileTop == null) {
      return movingCardData.value === "king";
    }
    const pileTopCardData = getCardData(pileTop)?.card;
    if (pileTopCardData == null) {
      return movingCardData.value === "king";
    }

    // можем положить только карты другого цвета и значение меньше на 1
    return this.isPileChainable(movingCardData, pileTopCardData);
  }

  // cочетаются ли карты в рабочей стопке - не проверяй стопку
  public isPileChainable(top: IKlondikeCardData, bottom: IKlondikeCardData): boolean {
    return !this.isSameColor(top.suit, bottom.suit) && this.cardOrder(bottom.value) === this.cardOrder(top.value) + 1;
  }

  // cочетаются ли карты в базе - не проверяй стопку
  public isBaseChainable(top: IKlondikeCardData, bottom: IKlondikeCardData): boolean {
    return top.suit === bottom.suit && this.cardOrder(bottom.value) === this.cardOrder(top.value) - 1;
  }

  private cardOrder(value: CardValue): number {
    return this.valueOrder.indexOf(value);
  }

  private isRed(suit: CardSuit): boolean {
    return suit === CardSuit.heart || suit === CardSuit.diamond;
  }

  private isSameColor(suit1: CardSuit, suit2: CardSuit): boolean {
    return this.isRed(suit1) === this.isRed(suit2);
  }
}
