import { Align, AlignObject } from "@kvisaz/phaser-sugar";
import {
  cardClassic52Deck,
  CardSuit,
  CardValue,
  CommonGameObject,
  DataCardView,
  GameObjectBuilder,
  IPlayCard,
  makeArray,
} from "../../../common";
import { CardAssetBuilder } from "../../../assets";
import { IBoundable } from "../../../common/games/cards-abstract/abstract_types";
import { KlondikeSolitaireRules } from "./KlondikeSolitaireRules";

interface IProps {
  scene: Phaser.Scene;
  locale: "en" | "ru";
  fieldBounds: { getBounds: () => Phaser.Geom.Rectangle };
  builders: {
    // колода
    deckZone: GameObjectBuilder;
    // кладбище
    graveZone: GameObjectBuilder;
    // базы для складывания
    baseBuilder: GameObjectBuilder;
    // рабочие стопки
    pileBuilder: GameObjectBuilder;
  };
  cardLayout: {
    deck: (items: AlignObject[], inputZone: IBoundable) => void;
    grave: (items: AlignObject[], inputZone: IBoundable) => void;
    base: (items: AlignObject[], inputZone: IBoundable) => void;
    pile: (items: AlignObject[], inputZone: IBoundable) => void;
  };
}

type GameCardView = DataCardView<IPlayCard>;

export class KlondikeView_Prev_Version_0 {
  private readonly align = new Align();
  private readonly klondikeRules = new KlondikeSolitaireRules();

  private readonly zones: {
    deck: CommonGameObject;
    grave: CommonGameObject;
    bases: CommonGameObject[];
    piles: CommonGameObject[];
  };
  private readonly cardViews: GameCardView[];

  private cardCollections: {
    deck: GameCardView[];
    grave: GameCardView[];
    bases: GameCardView[][];
    piles: GameCardView[][];
  };

  constructor(private props: IProps) {
    this.zones = this.createZones();
    this.cardViews = this.createCards();
    this.cardCollections = this.initStartPiles();
    this.dealInitialTableau();
    this.placeDeckCards();

    /** все начинается с реакции колоды на клик **/
    this.addDeckInput();
  }

  private createZones() {
    console.log("KlondikeView_Prev_Version_0 create Zones");
    const { align, props, klondikeRules } = this;
    const { scene, builders, fieldBounds } = props;

    const deck = builders.deckZone().setInteractive({ useHandCursor: true });
    const grave = builders.graveZone().setInteractive({ useHandCursor: true });

    const bases = makeArray(klondikeRules.BASE_AMOUNT).map(() =>
      builders.baseBuilder().setInteractive({ useHandCursor: true }),
    );
    const piles = makeArray(klondikeRules.PILES_AMOUNT).map(() =>
      builders.pileBuilder().setInteractive({ useHandCursor: true }),
    );

    const padding = 16;
    align.anchor(fieldBounds).leftIn(deck).topIn(deck);
    align.anchor(deck).rightTo(grave, padding).centerY(grave);

    const baseBounds = bases[0].getBounds();
    bases.forEach((base, i) => {
      align
        .anchor(fieldBounds)
        .rightIn(base, -(baseBounds.width + padding) * i)
        .topIn(base);
    });

    const pileBounds = piles[0].getBounds();
    piles.forEach((pile, i) => {
      align
        .anchor(bases[0])
        .rightIn(pile, -(pileBounds.width + padding) * i)
        .bottomTo(pile, padding * 3);
    });

    return {
      deck,
      grave,
      bases,
      piles,
    };
  }

  private createCards() {
    const { align, props } = this;
    const { scene, builders, locale } = props;

    /** select data for cardCollections **/
    const playCards = Phaser.Utils.Array.Shuffle([...cardClassic52Deck.cards.all]);
    console.log("playCards", playCards);

    /** card builder **/
    const cardAssetBuilder = new CardAssetBuilder({ scene, locale });
    const cardBuilder = (suit: CardSuit, value: CardValue) => {
      return new DataCardView<IPlayCard>({
        scene,
        initState: "back",
        card: { suit, value },
        faceImage: cardAssetBuilder.cardFace(suit, value),
        backImage: cardAssetBuilder.back(),
      }).setScale(0.6);
    };

    /** cardViews **/
    const cardViews = playCards.map((playCard) => {
      const cardView = cardBuilder(playCard.suit, playCard.value);
      cardView.setData("id", `${playCard.suit}-${playCard.value}`);
      cardView.enableClick(false);
      return cardView;
    });

    return cardViews;
  }

  private initStartPiles() {
    const piles = {
      deck: this.cardViews,
      grave: [],
      bases: makeArray(this.klondikeRules.BASE_AMOUNT).map(() => {
        return [];
      }),
      piles: makeArray(this.klondikeRules.PILES_AMOUNT).map(() => {
        return [];
      }),
    };
    this.cardCollections = piles;
    return piles;
  }

  /**
   * Раскладывает стартовые карты по рабочим стопкам согласно правилам пасьянса «Косынка».
   */
  private dealInitialTableau() {
    const { cardCollections, klondikeRules, props, zones } = this;
    const { cardLayout } = props;

    for (let row = 0; row < klondikeRules.PILES_AMOUNT; row++) {
      for (let pileIndex = row; pileIndex < klondikeRules.PILES_AMOUNT; pileIndex++) {
        const card = this.getTopCard(cardCollections.deck);
        if (!card) {
          return;
        }
        const pile = cardCollections.piles[pileIndex];
        pile.push(card);
        if (pileIndex === row) {
          card.flip("face");
        } else {
          card.flip("back");
        }
        card.makeTop();
      }
    }

    cardCollections.piles.forEach((pile, index) => {
      cardLayout.pile(pile, zones.piles[index]);
    });
  }

  /** все карты складывают в колоду **/
  private placeDeckCards() {
    const { align, props, cardViews, zones, cardCollections } = this;
    const { scene, cardLayout } = props;

    cardLayout.deck(cardCollections.deck, zones.deck);
  }

  private createInputLogic() {
    this.addDeckInput();
  }

  /** private card 'getters' **/
  private getTopCard(pile: GameCardView[]) {
    return pile.pop();
  }

  /** private input, may be on once?? **/
  private addDeckInput() {
    this.zones.deck.once(Phaser.Input.Events.GAMEOBJECT_POINTER_UP, () => {
      const topDeckCard = this.getTopCard(this.cardCollections.deck);
      if (topDeckCard) {
        this.moveFromDeckToGrave([topDeckCard], () => this.addDeckInput());
      } else {
        this.moveAllFromGraveToDeck(() => this.addDeckInput());
      }
    });
  }

  /** private animations with onComplete Callback **/
  private moveFromDeckToGrave(cards: GameCardView[], onComplete?: () => void) {
    const { align, props, cardViews, zones, cardCollections } = this;
    const { scene, cardLayout } = props;
    cards.forEach((card) => {
      this.cardCollections.grave.push(card);
      card.flip("face");
      card.makeTop();
    });
    cardLayout.deck(cardCollections.grave, zones.grave);

    onComplete?.();
  }

  private moveAllFromGraveToDeck(onComplete?: () => void) {
    const graveCards = this.cardCollections.grave;
    this.cardCollections.grave = [];

    /** Из grave в deck Перекладываем в обратном порядке! **/
    for (let i = graveCards.length - 1; i >= 0; i--) {
      const card = graveCards[i];
      this.cardCollections.deck.push(card);
      card.flip("back");
      card.makeTop();
    }

    this.props.cardLayout.deck(this.cardCollections.deck, this.zones.deck);

    onComplete?.();
  }
}
