import { ASSETS, BackgroundAssetBuilder, CardAssetBuilder, getCurrentLocale } from "../../../assets";
import { services } from "../../../serviceProvider";
import { SoundManager } from "../../../ui";
import { addBackButton, addText } from "../utils";
import { Scenes } from "../../routes";
import {
  cardClassic52Deck,
  CardStack,
  CardSuit,
  CardValue,
  DataCardView,
  IPlayCard,
  resetSearchParam,
} from "../../../common";
import { Align } from "@kvisaz/phaser-sugar";
import { addCardZone } from "./cardUtils";
import { centeredCardLayoutStrategy, showValueCardFromTopLayoutStrategy } from "../../../common/games/cards-layout";

export class CardStackScene extends Phaser.Scene {
  preload() {}

  create() {
    const scene = this;
    const { soundMusicSettings } = services;
    const soundManager = new SoundManager({ scene, soundMusicSettings });
    new BackgroundAssetBuilder(scene).sceneBg();
    const align = new Align();

    const soundNames = Object.keys(ASSETS.sounds.effect);
    console.log(soundNames);

    /** backCover button **/
    addBackButton({
      scene: this,
      onClick: () => {
        resetSearchParam("test");
        scene.scene.start(Scenes.TestScene);
      },
    });

    /** Main test **/
    const title = addText(scene, "Card Stack test");
    align.anchorSceneScreen(scene).center(title).topIn(title, 10);
    this.add.existing(title);

    /** select data for cards **/
    const CARD_AMOUNT = 12;
    const playCards = cardClassic52Deck.cards.all.slice(0, CARD_AMOUNT);
    console.log("playCards", playCards);

    /** card builder **/
    const cardAssetBuilder = new CardAssetBuilder({ scene, locale: getCurrentLocale() });
    const cardBuilder = (suit: CardSuit, value: CardValue) => {
      return new DataCardView<IPlayCard>({
        scene,
        initState: "back",
        card: { suit, value },
        faceImage: cardAssetBuilder.cardFace(suit, value),
        backImage: cardAssetBuilder.back(),
      })
        .enableClick(true)
        .setOnClick((card) => {
          card.flip();
          console.log("card flip", card);
        });
    };

    /** create target zones  before **/
    const cardZone1 = addCardZone({ scene, cssColor: "#98651c" });
    align.anchorSceneScreen(scene).leftIn(cardZone1, 100).topIn(cardZone1, 100);

    const cardZone2 = addCardZone({ scene, cssColor: "#3af449" });
    align.anchorSceneScreen(scene).rightIn(cardZone2, -100).topIn(cardZone2, 100);

    /** cardViews **/
    const cardViews = playCards.map((playCard) => {
      const cardView = cardBuilder(playCard.suit, playCard.value);
      cardView.enableClick(false);
      return cardView;
    });

    const label1 = addText(scene, `${cardViews.length}`);
    align.anchor(cardZone1).centerX(label1).bottomTo(label1, 1);
    scene.add.existing(label1);

    const label2 = addText(scene, "0");
    align.anchor(cardZone2).centerX(label2).bottomTo(label2, 1);
    scene.add.existing(label2);

    /** deck **/
    const cardDeck1 = new CardStack<IPlayCard>({
      inputZone: cardZone1,
      /** ограниченное смещение чтобы просто показать эффект колоды **/
      layoutStrategy: centeredCardLayoutStrategy,
    })
      .add(cardViews)
      .setOnClick((stack) => {
        const activeCards = stack.get({ amount: 1 });
        activeCards.forEach((card) => card.flip("face"));
        cardDeck2.add(activeCards);
        label1.setText(`${cardDeck1.length}`);
        label2.setText(`${cardDeck2.length}`);
      })
      .enableClick(true);

    const cardDeck2 = new CardStack<IPlayCard>({
      inputZone: cardZone2,
      /** вторая зона показывает всем карты со смещением - как в пасьянсе **/
      layoutStrategy: showValueCardFromTopLayoutStrategy,
    })
      .setOnClick((stack) => {
        const activeCards = stack.get({ amount: 1 });
        activeCards.forEach((card) => card.flip("face"));
        cardDeck1.add(activeCards);
        label1.setText(`${cardDeck1.length}`);
        label2.setText(`${cardDeck2.length}`);
      })
      .enableClick(true);

    /** add to deck **/

    /**
     *  todo 1 - flip on click
     *  todo 2 - test colode
     *  todo 3 - animation fly
     * **/
  }
}
