import { ASSETS, BackgroundAssetBuilder, CardAssetBuilder, getCurrentLocale } from "../../../assets";
import { services } from "../../../serviceProvider";
import { SoundManager } from "../../../ui";
import { addBackButton, addText } from "../utils";
import { Scenes } from "../../routes";
import {
  cardClassic52Deck,
  CardSuit,
  CardValue,
  DataCardView,
  IPlayCard,
  resetSearchParam,
  setContainerInteractive,
} from "../../../common";
import { Align, cssColorToInt } from "@kvisaz/phaser-sugar";

export class CardDragScene extends Phaser.Scene {
  preload() {}

  create() {
    const scene = this;
    const { soundMusicSettings } = services;
    const soundManager = new SoundManager({ scene, soundMusicSettings });
    new BackgroundAssetBuilder(scene).sceneBg();
    const align = new Align();

    const soundNames = Object.keys(ASSETS.sounds.effect);
    console.log(soundNames);

    /** backCover button **/
    addBackButton({
      scene: this,
      onClick: () => {
        resetSearchParam("test");
        scene.scene.start(Scenes.TestScene);
      },
    });

    /** Main test **/
    const title = addText(scene, "Card Drag Drop test");
    align.anchorSceneScreen(scene).center(title).topIn(title, 10);
    this.add.existing(title);

    /** select data for cards **/
    const CARD_AMOUNT = 12;
    const playCards = cardClassic52Deck.cards.all.slice(0, CARD_AMOUNT);
    console.log("playCards", playCards);

    /** card builder **/
    const cardAssetBuilder = new CardAssetBuilder({ scene, locale: getCurrentLocale() });
    const cardBuilder = (suit: CardSuit, value: CardValue) => {
      return new DataCardView<IPlayCard>({
        scene,
        initState: "back",
        card: { suit, value },
        faceImage: cardAssetBuilder.cardFace(suit, value),
        backImage: cardAssetBuilder.back(),
      });
    };

    /** cardViews **/
    const cardViews = playCards.map((playCard) => {
      const cardView = cardBuilder(playCard.suit, playCard.value);
      cardView.enableClick(false);

      setContainerInteractive(cardView);

      return cardView;
    });

    /** просто размещаем карты на сцене **/
    cardViews.forEach((cardView) => {
      align.anchorSceneScreen(scene).leftIn(cardView, 100).topIn(cardView, 200);
    });

    /** дроп зоны **/
    function getDropZoneId(dropZone: Phaser.GameObjects.GameObject) {
      return dropZone.getData("dropZoneData") as string | undefined;
    }

    function setDropZoneId(dropZone: Phaser.GameObjects.GameObject, id: string) {
      dropZone.setData("dropZoneData", id);
    }

    function addDropZone({ scene, width, height }: { scene: Phaser.Scene; width: number; height: number }) {
      return new Phaser.GameObjects.Zone(scene, 0, 0, width, height).setRectangleDropZone(width, height);
    }

    const dropZone1Color = cssColorToInt("#a4dfc0");
    const dropZone1 = addDropZone({
      scene,
      width: 300,
      height: 400,
    });
    setDropZoneId(dropZone1, "1");
    scene.add.existing(dropZone1);
    align.anchorSceneScreen(scene).rightIn(dropZone1, -10).centerY(dropZone1);

    const dropZone1Rect = new Phaser.GameObjects.Rectangle(
      scene,
      0,
      0,
      dropZone1.width,
      dropZone1.height,
      dropZone1Color,
      0.75,
    ).setStrokeStyle(4, dropZone1Color);
    scene.add.existing(dropZone1Rect);
    align.anchor(dropZone1).center(dropZone1Rect);

    const dropZone2 = addDropZone({
      scene,
      width: 300,
      height: 400,
    });
    scene.add.existing(dropZone2);
    setDropZoneId(dropZone2, "2");
    align.anchorSceneScreen(scene).rightIn(dropZone2, -410).centerY(dropZone2);

    const dropZone2Color = cssColorToInt("#98651c");
    const dropZone2Rect = new Phaser.GameObjects.Rectangle(
      scene,
      0,
      0,
      dropZone2.width,
      dropZone2.height,
      dropZone2Color,
      0.75,
    ).setStrokeStyle(4, dropZone2Color);
    scene.add.existing(dropZone2Rect);
    align.anchor(dropZone2).center(dropZone2Rect);

    /** логика драггингга **/
    type DragObject = Phaser.GameObjects.GameObject & {
      x: number;
      y: number;
      input: Phaser.Types.Input.InteractiveObject;
    };

    type DropZone = Phaser.GameObjects.GameObject & {};

    /** делаем карты драггабельными **/
    scene.input.setDraggable(cardViews);

    /** делаем зоны дропабельными **/

    /** обработка событий **/
    scene.input.on(Phaser.Input.Events.DRAG_START, (pointer: Phaser.Input.Pointer, gameObject: DragObject) => {
      scene.children.bringToTop(gameObject);
    });

    scene.input.on(
      Phaser.Input.Events.DRAG,
      (pointer: Phaser.Input.Pointer, gameObject: DragObject, dragX: number, dragY: number) => {
        gameObject.x = dragX;
        gameObject.y = dragY;
      },
    );

    scene.input.on(
      Phaser.Input.Events.DRAG_ENTER,
      (pointer: Phaser.Input.Pointer, gameObject: DragObject, dropZone: DropZone) => {
        const id = getDropZoneId(dropZone);
        console.log("enter", id);
      },
    );

    scene.input.on(
      Phaser.Input.Events.DRAG_LEAVE,
      (pointer: Phaser.Input.Pointer, gameObject: DragObject, dropZone: DropZone) => {
        const id = getDropZoneId(dropZone);
        console.log("enter", id);
      },
    );

    scene.input.on(
      Phaser.Input.Events.DROP,
      (pointer: Phaser.Input.Pointer, gameObject: DragObject, dropZone: DropZone) => {
        const id = getDropZoneId(dropZone);
        console.log("drop", id);
      },
    );

    scene.input.on(
      Phaser.Input.Events.DRAG_END,
      (pointer: Phaser.Input.Pointer, gameObject: DragObject, dropped: boolean) => {
        console.log(`DRAG_END
        dropped ${dropped}
        `);

        if (!dropped) {
          /** крутой хак для драггинга, надо будет анимацию прикрутить **/
          gameObject.x = gameObject.input.dragStartX;
          gameObject.y = gameObject.input.dragStartY;
        }
      },
    );
  }
}
