import { ASSETS, BackgroundAssetBuilder, CardAssetBuilder, getCurrentLocale } from "../../../assets";
import { services } from "../../../serviceProvider";
import { SoundManager } from "../../../ui";
import { addBackButton, addText } from "../utils";
import { Scenes } from "../../routes";
import {
  addDragDropZen,
  cardClassic52Deck,
  CardSuit,
  CardValue,
  DataCardView,
  DropZone,
  IPlayCard,
  resetSearchParam
} from "../../../common";
import { Align, cssColorToInt } from "@kvisaz/phaser-sugar";
import { centeredCardLayoutStrategy } from "../../../common/games/cards-layout";

/** todo - теперь упакуй это компактно в хелперы **/
export class CardMyDragScene extends Phaser.Scene {
  preload() {}

  create() {
    const scene = this;
    const { soundMusicSettings } = services;
    const soundManager = new SoundManager({ scene, soundMusicSettings });
    new BackgroundAssetBuilder(scene).sceneBg();
    const align = new Align();

    const soundNames = Object.keys(ASSETS.sounds.effect);
    console.log(soundNames);

    /** backCover button **/
    addBackButton({
      scene: this,
      onClick: () => {
        resetSearchParam("test");
        scene.scene.start(Scenes.TestScene);
      },
    });

    /** Main test **/
    const title = addText(scene, "My Drop System");
    align.anchorSceneScreen(scene).center(title).topIn(title, 10);
    this.add.existing(title);

    /** select data for cards **/
    const CARD_AMOUNT = 12;
    const playCards = cardClassic52Deck.cards.all.slice(0, CARD_AMOUNT);
    console.log("playCards", playCards);

    /** card builder **/
    const cardAssetBuilder = new CardAssetBuilder({ scene, locale: getCurrentLocale() });
    const cardBuilder = (suit: CardSuit, value: CardValue) => {
      return new DataCardView<IPlayCard>({
        scene,
        initState: "back",
        card: { suit, value },
        faceImage: cardAssetBuilder.cardFace(suit, value),
        backImage: cardAssetBuilder.back(),
      });
    };

    /** cardViews **/
    const cardViews = playCards.map((playCard) => {
      const cardView = cardBuilder(playCard.suit, playCard.value);
      cardView.setData("id", `${playCard.suit}-${playCard.value}`);
      cardView.enableClick(false);
      return cardView;
    });

    /** просто размещаем карты на сцене **/
    const deckZone1Color = cssColorToInt("#a4dfc0");
    const deckZone1 = new Phaser.GameObjects.Rectangle(scene, 0, 0, 300, 400, deckZone1Color, 0.75).setStrokeStyle(
      4,
      deckZone1Color,
    );
    scene.add.existing(deckZone1);
    scene.children.moveBelow(deckZone1, cardViews[0]);
    align.anchorSceneScreen(scene).leftIn(deckZone1, 100).topIn(deckZone1, 200);
    centeredCardLayoutStrategy(cardViews, deckZone1, {
      cardOffset: 30
    });

    /** дроп зоны **/
    const dropZone1Color = cssColorToInt("#a4dfc0");
    const dropZone1 = new Phaser.GameObjects.Rectangle(scene, 0, 0, 300, 400, dropZone1Color, 0.75).setStrokeStyle(
      4,
      dropZone1Color,
    );
    scene.add.existing(dropZone1);
    align.anchorSceneScreen(scene).centerY(dropZone1).rightIn(dropZone1, -20);
    dropZone1.setData("id", "1");

    const dropZone2Color = cssColorToInt("#98651c");
    const dropZone2 = new Phaser.GameObjects.Rectangle(scene, 0, 0, 300, 400, dropZone2Color, 0.75).setStrokeStyle(
      4,
      dropZone2Color,
    );
    scene.add.existing(dropZone2);
    align.anchorSceneScreen(scene).centerY(dropZone2).rightIn(dropZone2, -350);
    dropZone2.setData("id", "2");

    const dropZoneEnter = (dropZone: DropZone, dragObject: Phaser.GameObjects.GameObject) => {
      dropZone.setScale(1.1);
    };

    const dropZoneLeave = (dropZone: DropZone, dragObject: Phaser.GameObjects.GameObject) => {
      dropZone.setScale(1);
    };

    addDragDropZen({
      dragObjects: cardViews,
      dropZones: [dropZone1, dropZone2],
      onDragStart: (dragObject) => {
        console.log("onDragStart", dragObject.getData("id"));
      },
      isDroppable: (dragObject, dropZone) => {
        console.log("isDroppable", dragObject.getData("id"), dropZone.getData("id"));
        return true;
      },
      onDropZoneEnter: (dragObject, dropZone) => {
        dropZoneEnter(dropZone, dragObject);
        console.log("onDropZoneEnter", dragObject.getData("id"), dropZone.getData("id"));
      },
      onDropZoneLeave: (dragObject, dropZone) => {
        dropZoneLeave(dropZone, dragObject);
        console.log("onDropZoneLeave", dragObject.getData("id"), dropZone.getData("id"));
      },
      onDropReset: (dragObject) => {
        console.log("onDropReset", dragObject.getData("id"));
      },
      onDrop: (dragObject, dropZone) => {
        console.log("onDrop", dragObject.getData("id"), dropZone.getData("id"));
        align.anchor(dropZone).center(dragObject);
      },
    });
  }
}
