import { CardSide } from "../../../common/games/cards-abstract/abstract_types";
import { CardSuit, CardValue } from "../../../common";
import { IKlondikeStackData } from "./KlondikeStack";

export function getCardStack(card: Phaser.GameObjects.GameObject): IKlondikeStackData | undefined {
  return card.getData("stack");
}

export interface IKlondikeCardData {
  suit: CardSuit;
  value: CardValue;
}

type CardData = {
  card: IKlondikeCardData;
  side: CardSide;
  stack: IKlondikeStackData;
};

export function getCardData(card: Phaser.GameObjects.GameObject): CardData | undefined {
  const cardData = card.getData("card") as IKlondikeCardData | undefined;
  const side = card.getData("side") as CardSide | undefined;
  const stack = getCardStack(card);

  if (cardData == null || side == null || stack == null) return;

  return {
    card: cardData,
    side,
    stack,
  };
}

export function setCardSuitValueData(card: Phaser.GameObjects.GameObject, data: IKlondikeCardData) {
  return card.setData("card", data);
}
