import { CardSide, IBoundable, ILayoutStrategy } from "../../../common/games/cards-abstract/abstract_types";
import { IKlondikeCard } from "./interfaces";
import { ArrangeOrder, arrangeOrder } from "../../../common";
import * as Phaser from "phaser";

export enum KlondikeStackType {
  DECK = "deck",
  GRAVE = "grave",
  BASE = "base",
  PILE = "pile",
}

interface ICardPlace extends Phaser.GameObjects.GameObject {
  getBounds: () => Phaser.Geom.Rectangle;
}

interface IKlondikeCardStackProps {
  id: string;
  type: KlondikeStackType;
  /** Где лежат карты **/
  cardPlace: ICardPlace;
  /** как карты раскладываются на визуальном месте **/
  layoutStrategy: ILayoutStrategy;
  /** начальный сетап карт **/
  cards?: IKlondikeCard[];
}

export interface IKlondikeStackData {
  id: string;
  type: KlondikeStackType;
}

export class KlondikeStack implements IBoundable {
  private readonly cardPlace: ICardPlace;
  private readonly cards: IKlondikeCard[];
  public readonly data: IKlondikeStackData;

  getCards() {
    return this.cards;
  }

  constructor(private props: IKlondikeCardStackProps) {
    this.data = { id: props.id, type: props.type };
    this.cardPlace = this.props.cardPlace;
    this.cards = this.props.cards != null ? [...this.props.cards] : [];
    this.setStackDataToAll();
    this.layout();
  }

  get length() {
    return this.cards.length;
  }

  getBounds(): Phaser.Geom.Rectangle {
    return this.cardPlace.getBounds();
  }


  layout() {
    this.props.layoutStrategy(this.cards, this.cardPlace);
  }

  /** Забирает карту из стопки **/
  pickTopCard() {
    return this.cards.pop();
  }

  flipTopCard(toSide: CardSide = "face") {
    return this.cards[this.cards.length - 1]?.flip(toSide);
  }

  /** Смотрит на карту, ничего с ней не делая, индекс с верху **/
  lookAtCard(indexFromTop = 0) {
    return this.cards[this.cards.length - 1 - indexFromTop];
  }

  placeCardOnTop(card: IKlondikeCard, cardSide: CardSide = "face") {
    arrangeOrder(card, ArrangeOrder.top);
    card.flip(cardSide);
    this.cards.push(card);
    this.layout();
    this.setStackData(card);
  }

  place(cards: IKlondikeCard[]) {
    if (cards.length === 0) return;
    cards.forEach((card) => {
      arrangeOrder(card, ArrangeOrder.top);
      this.cards.push(card);
    });
    this.setStackDataToAll();
    this.layout();
  }

  removeCard(card: IKlondikeCard) {
    const index = this.cards.indexOf(card);
    if (index === -1) return;
    this.cards.splice(index, 1);
    this.resetStackData(card);
    this.layout();
  }

  /** перемещает в том же порядке **/
  moveAllToStack(stack: KlondikeStack) {
    const cards = [...this.cards];
    this.cards.length = 0;
    stack.place(cards);
  }

  /** перемещает как в колоду - восстанавливая порядок и переворачивая карты **/
  moveAsToDeck(stack: KlondikeStack) {
    const cards = [...this.cards].reverse();
    this.cards.length = 0;
    stack.place(cards);
    cards.forEach((card) => card.flip("back"));
  }

  /** private marker **/
  private resetStackData(obj: Phaser.GameObjects.GameObject) {
    obj.setData("stack", undefined);
  }

  private setStackData(obj: Phaser.GameObjects.GameObject) {
    obj.setData("stack", { ...this.data });
  }

  private setStackDataToAll() {
    this.cards.forEach((card) => {
      this.setStackData(card);
    });
  }
}
