import { Align } from "@kvisaz/phaser-sugar";
import { CardViewState, ICard } from "./index";

type Image = Phaser.GameObjects.Container | Phaser.GameObjects.Image;

interface IProps<CardData> {
  scene: Phaser.Scene;
  /** состояние карты - открыто / закртоы **/
  initState?: CardViewState;
  /** любые дополнительные данные **/
  card: CardData;

  faceImage: Image;
  backImage: Image;

  dontAddToScene?: boolean;
}

/**
 * Контейнер для любого вида карточек
 * просто добавь свои данные
 * и используй аниматор для движений (или зашьем анимации тут?)
 * **/
export class DataCardView<CardData> extends Phaser.GameObjects.Container implements ICard<CardData> {
  private inputZone: Phaser.GameObjects.Zone;
  private readonly faceImage: Image;
  private readonly backImage: Image;
  private onClick?: (card: DataCardView<CardData>) => void;
  private onClickEvent = Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN;

  constructor(props: IProps<CardData>) {
    super(props.scene, 0, 0);
    const { scene } = props;

    this.setData("viewState", props.initState ?? "face");
    this.setData("cardState", props.card);
    this.faceImage = props.faceImage;
    this.backImage = props.backImage;
    const bounds = this.faceImage.getBounds();
    this.inputZone = new Phaser.GameObjects.Zone(scene, 0, 0, bounds.width, bounds.height);

    new Align()
      .anchor(this.backImage)
      .center(this.faceImage)
      .center(this.inputZone as unknown as Phaser.GameObjects.Container);
    this.add([this.backImage, this.faceImage, this.inputZone]);

    this.updateImages();

    if (!props.dontAddToScene) {
      scene.add.existing(this);
    }
    //
    // /** позволяет делать контейнеры интерактивными **/
    const myBounds = this.getBounds();
    this.setSize(myBounds.width, myBounds.height);
  }

  /** data getters and setters **/
  private get viewState(): CardViewState {
    return this.getData("viewState") as CardViewState;
  }

  get isFaceUp(): boolean {
    return this.viewState === "face";
  }

  /** изменение состояния только внутри **/
  private set viewState(state: CardViewState) {
    this.setData("viewState", state);
  }

  get card(): CardData {
    return this.getData("cardState") as CardData;
  }

  /** вряд ли должно использоваться снаружи **/
  set card(card: Partial<CardData>) {
    const newCard = { ...this.card, ...card };
    this.setData("cardState", newCard);
  }

  /** public card methods **/

  /** Reveal the card face */
  flip(to?: CardViewState): void {
    /** то же состояние - возврат **/
    if (this.viewState === to) {
      return;
    }

    if (to != null) {
      this.viewState = to;
    } else {
      const prevState = this.viewState;
      this.viewState = prevState === "face" ? "back" : "face";
    }

    /** новое состояние **/
    this.updateImages();
  }

  setOnClick(onClick: (card: DataCardView<CardData>) => void): this {
    this.onClick = onClick;
    return this;
  }

  enableClick(enabled: boolean): this {
    const inputZone = this.inputZone;
    if (enabled) {
      inputZone.setInteractive({ useHandCursor: true });
      inputZone.on(this.onClickEvent, () => this.onClick?.(this));
    } else {
      inputZone.disableInteractive();
      inputZone.off(this.onClickEvent);
    }
    return this;
  }

  makeTop(): ICard<CardData> {
    const parentContainer = this.parentContainer ?? this.scene.children;
    parentContainer.bringToTop(this);
    return this;
  }

  makeLowest(): ICard<CardData> {
    const parentContainer = this.parentContainer ?? this.scene.children;
    parentContainer.sendToBack(this);
    return this;
  }

  /** private card methods **/

  /** Показываем картинку согласно состоянию */
  private updateImages(): void {
    this.faceImage.setVisible(this.isFaceUp);
    this.backImage.setVisible(!this.isFaceUp);
  }
}
