import { AlignObject } from "@kvisaz/phaser-sugar";
import { ICard, ICardCollection, ICardStack, IGetArgs } from "./index";
import { IBoundable, ILayoutStrategy } from "./abstract_types";
import { centeredCardLayoutStrategy, fromTopCardLayoutStrategy } from "../cards-layout";

type InputZone = Phaser.GameObjects.Zone | Phaser.GameObjects.Rectangle;

interface IProps {
  /**
   * она же работает как место для выравниваиня
   * логично? логично
   * **/
  inputZone: InputZone;

  /** стратегия макетирования **/
  layoutStrategy?: ILayoutStrategy;
}

/** Задача колоды - простая манипуляицмия карточками и расположение их в одном месте
 * ПОМНИ ЧТО КАРТЫ РАСПОЛАГАЮТСЯ ПРЯМО НА СЦЕНЕ, никаких контейнеров
 * **/
export class CardStack<CardData> implements ICardStack<CardData>, ICardCollection<ICard<CardData>> {
  /** последние - самые верхние **/
  private cards: ICard<CardData>[] = [];

  /** input zone **/
  private readonly inputZone: InputZone;
  private readonly layoutStrategy: ILayoutStrategy;

  private onClick: undefined | ((stack: ICardStack<CardData>) => void);
  private onClickEvent = Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN;

  constructor({ inputZone, layoutStrategy = centeredCardLayoutStrategy }: IProps) {
    this.inputZone = inputZone;
    this.layoutStrategy = layoutStrategy;
  }

  setOnClick(onClick: (stack: ICardStack<CardData>) => void): this {
    this.onClick = onClick;
    return this;
  }

  enableClick(enabled: boolean): this {
    const inputZone = this.inputZone;
    if (enabled) {
      inputZone.setInteractive({ useHandCursor: true });
      inputZone.on(this.onClickEvent, () => this.onClick?.(this));
    } else {
      inputZone.setInteractive({ useHandCursor: false });
      inputZone.off(this.onClickEvent);
    }
    return this;
  }

  get length(): number {
    return this.cards.length;
  }

  add(cards: ICard<CardData>[], to = "top"): this {
    cards.forEach((card) => {
      this.cards.push(card);
      if (to === "top") {
        card.makeTop();
      } else {
        card.makeLowest();
      }
    });
    this.layout();
    return this;
  }

  // взять карточки снизу или сверху, брать случайно не имеет смысла - просто перемешай сначала и бери потом
  // При взятии колода по умолчанию уменьшается на эти карточки
  get({ amount, from = "top", isNotRemoving = false }: IGetArgs): ICard<CardData>[] {
    if (amount <= 0) {
      return [];
    }

    let extractedCards: ICard<CardData>[];

    if (from === "bottom") {
      // Извлекаем карты с начала массива (низ колоды)
      extractedCards = this.cards.slice(0, amount);
      if (!isNotRemoving) {
        // Удаляем извлеченные карты
        this.cards = this.cards.slice(amount);
      }
    } else {
      // Извлекаем карты с конца массива (верх колоды)
      extractedCards = this.cards.slice(-amount);
      if (!isNotRemoving) {
        // Удаляем извлеченные карты
        this.cards = this.cards.slice(0, this.cards.length - amount);
      }
    }

    return extractedCards;
  }

  reverse(): this {
    this.cards.reverse();
    return this;
  }

  shuffle(): this {
    this.cards.sort(() => Math.random() - 0.5);
    return this;
  }

  /**
   * PRIVATE
   * **/

  /** Выравнять карточки визуально на заданном месте - **/
  private layout(): void {
    const place: IBoundable = this.inputZone;
    if (place == null) return;
    this.layoutStrategy(this.cards as unknown as AlignObject[], place);
  }
}
